// Change these, then save. The other nodes of this workflow read them from here.
const SESSION_GAP_MINUTES = 30; // on one phone, a pause longer than this starts a new play session
const DAY_FIRST = true; // 03/04/2026 means 3 April. Set to false if your app writes month/day/year
const TEMP_MIN = -20; // a temperature outside this range is refused as a typing mistake
const TEMP_MAX = 100;
const MAX_ROWS = 2000; // a file with more rows than this is refused
// Used only for a file without a header row: what the columns mean, by how many there are.
const COLUMNS_WITHOUT_HEADER = {
  4: ['battery', 'temperature', 'frame_drops', 'note'],
  5: ['time', 'battery', 'temperature', 'frame_drops', 'note'],
  6: ['time', 'device', 'battery', 'temperature', 'frame_drops', 'note'],
};

const upload = $input.first();
return [
  {
    json: {
      session_gap_minutes: SESSION_GAP_MINUTES,
      day_first: DAY_FIRST,
      temp_min: TEMP_MIN,
      temp_max: TEMP_MAX,
      max_rows: MAX_ROWS,
      columns_without_header: COLUMNS_WITHOUT_HEADER,
      // One name per run: rows and the file record carry it, so a run can tell its own rows from another run's.
      token: `${$execution.id}-${Math.random().toString(36).slice(2, 10)}`,
      request: upload.json,
    },
    binary: upload.binary, // an uploaded file travels on to "Read the upload"
  },
];

// Finds the CSV text in the request, whichever way the phone sent it:
//   1. a file upload (multipart form, any field name)
//   2. the raw text as the body (Content-Type text/csv, text/plain or none)
//   3. JSON or a form with the text in "csv" (also "text", "content", "data", "file")
// The phone can say which device it is with ?device=NAME in the address, a
// "device" field next to the file, or the header X-Device.

const item = $input.first();
const { request } = item.json;
const body = request.body;
const fields = body && typeof body === 'object' && !Array.isArray(body) ? body : {};

let bytes = null;
let form = 'none';
let filename = '';

const files = Object.keys(item.binary ?? {});
if (files.length > 0) {
  const file = item.binary[files[0]];
  bytes = await this.helpers.getBinaryDataBuffer(0, files[0]);
  // n8n stores a raw body as a file too; only a multipart upload has fields or a real file name.
  form = String(request.headers['content-type'] ?? '').startsWith('multipart/') ? 'file upload' : 'raw body';
  filename = form === 'file upload' ? String(file.fileName ?? '') : '';
} else if (typeof body === 'string') {
  bytes = Buffer.from(body, 'utf8');
  form = 'raw body';
} else {
  const key = ['csv', 'text', 'content', 'data', 'file'].find((name) => typeof fields[name] === 'string' && fields[name].trim() !== '');
  if (key) {
    bytes = Buffer.from(fields[key], 'utf8');
    form = 'text field';
  }
}

// Bytes to text. A byte order mark at the start says which encoding it is and is not part of the first column name.
let text = '';
if (bytes) {
  if (bytes.length >= 2 && bytes[0] === 0xff && bytes[1] === 0xfe) text = new TextDecoder('utf-16le').decode(bytes.subarray(2));
  else if (bytes.length >= 2 && bytes[0] === 0xfe && bytes[1] === 0xff) text = new TextDecoder('utf-16be').decode(bytes.subarray(2));
  else text = bytes.toString('utf8');
  text = text.replace(/^﻿/, '');
}

const pick = (value) => (typeof value === 'string' || typeof value === 'number' ? String(value).trim() : '');
return [
  {
    json: {
      form,
      text,
      filename: filename || pick(fields.filename) || pick(request.query?.filename),
      device: pick(request.query?.device) || pick(fields.device) || pick(request.headers['x-device']),
    },
  },
];

// Turns the uploaded text into checked rows, or into a clear answer for the
// phone when the file cannot be used. Nothing is written here.

// SHA-256 written out in plain JavaScript, because the Code node has no
// `crypto` and no `require`. Takes a string, hashes its UTF-8 bytes, returns
// 64 hex characters: the same value `sha256sum` prints for that text.
const K = [];
for (let n = 2, found = 0; found < 64; n++) {
  let prime = true;
  for (let d = 2; d * d <= n; d++) if (n % d === 0) prime = false;
  if (prime) K[found++] = Math.floor((Math.cbrt(n) % 1) * 4294967296);
}
function sha256(text) {
  const bytes = Buffer.from(String(text), 'utf8');
  const length = bytes.length;
  const padded = new Uint8Array((((length + 8) >> 6) + 1) << 6);
  padded.set(bytes);
  padded[length] = 0x80;
  const view = new DataView(padded.buffer);
  view.setUint32(padded.length - 8, Math.floor(length / 536870912));
  view.setUint32(padded.length - 4, (length << 3) >>> 0);
  const h = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const w = new Uint32Array(64);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let offset = 0; offset < padded.length; offset += 64) {
    for (let i = 0; i < 16; i++) w[i] = view.getUint32(offset + i * 4);
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3);
      const s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, hh] = h;
    for (let i = 0; i < 64; i++) {
      const t1 = (hh + (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) >>> 0;
      const t2 = ((rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) >>> 0;
      hh = g;
      g = f;
      f = e;
      e = (d + t1) >>> 0;
      d = c;
      c = b;
      b = a;
      a = (t1 + t2) >>> 0;
    }
    [a, b, c, d, e, f, g, hh].forEach((value, i) => {
      h[i] = (h[i] + value) >>> 0;
    });
  }
  return h.map((value) => value.toString(16).padStart(8, '0')).join('');
}

const settings = $('Settings').first().json;
const upload = $input.first().json;

const refuse = (code, error, message, extra = {}) => [{ json: { ok: false, code, error, message, form: upload.form, ...extra } }];

if (upload.form === 'none' || upload.text.trim() === '') {
  return refuse(
    400,
    'no_csv',
    'No CSV text arrived. Send the file as a form upload, or its text as the request body with Content-Type: text/csv, or JSON like {"csv": "..."}.',
  );
}

// Same text, same hash: line endings and a missing last line break do not make a file "new".
const text = upload.text.replace(/\r\n?/g, '\n').replace(/\s+$/, '');
const file_hash = sha256(text);

// --- split into records ------------------------------------------------------
// A field that starts with " runs to the closing ", and may hold the separator,
// line breaks and "" for a quote. Returns the records with the line each starts on.
function split(source, separator) {
  const records = [];
  let fields = [];
  let field = '';
  let quoted = false;
  let fieldStart = true;
  let line = 1;
  let startLine = 1;
  const endField = () => {
    fields.push(field);
    field = '';
    fieldStart = true;
  };
  const endRecord = () => {
    endField();
    if (fields.length > 1 || fields[0].trim() !== '') records.push({ line: startLine, fields });
    fields = [];
    startLine = line + 1;
  };
  for (let i = 0; i < source.length; i++) {
    const char = source[i];
    if (quoted) {
      if (char === '"' && source[i + 1] === '"') {
        field += '"';
        i++;
      } else if (char === '"') quoted = false;
      else {
        if (char === '\n') line++;
        field += char;
      }
    } else if (char === '"' && fieldStart) {
      quoted = true;
      fieldStart = false;
    } else if (char === separator) endField();
    else if (char === '\n') {
      endRecord();
      line++;
    } else {
      field += char;
      fieldStart = false;
    }
  }
  const openQuote = quoted;
  if (field !== '' || fields.length > 0 || openQuote) endRecord();
  return { records, openQuote };
}

// --- find the separator ------------------------------------------------------
// The first record decides how many columns there are; the separator that
// gives the most records with that many columns wins. One column never counts.
const NAMES = { ',': 'comma', ';': 'semicolon', '\t': 'tab', '|': 'pipe' };
let body = text;
let candidates = Object.keys(NAMES);
const hint = /^sep=(.)\n/i.exec(text); // a first line "sep=;" as Excel writes it
if (hint) {
  body = text.slice(hint[0].length);
  candidates = [hint[1]];
}
let best = null;
for (const separator of candidates) {
  const parsed = split(body, separator);
  const columns = parsed.records[0]?.fields.length ?? 0;
  if (columns < 2) continue;
  const score = parsed.records.filter((record) => record.fields.length === columns).length * columns;
  if (!best || score > best.score) best = { separator, columns, score, ...parsed };
}
const firstLine = body.split('\n')[0].slice(0, 120);
if (!best) {
  return refuse(
    422,
    'one_column',
    'The file has only one column per line, so nothing was stored. I looked for a comma, semicolon, tab or | between the values and found none in the first line. Check what the export writes between values.',
    { file_hash, first_line: firstLine },
  );
}
if (best.openQuote) {
  return refuse(
    422,
    'cut_off',
    'The file ends inside a quoted field, so it looks cut off. Nothing was stored. Send it again when the export is complete.',
    { file_hash, delimiter: NAMES[best.separator] },
  );
}

// --- which column is what ----------------------------------------------------
const fieldOf = (heading) => {
  const name = heading.toLowerCase().replace(/[^a-z0-9%°]/g, '');
  if (name === '') return null;
  if (/temp|°/.test(name)) return 'temperature';
  if (/drop|frame|jank|stutter/.test(name)) return 'frame_drops';
  if (/batt|charge|^bat%?$/.test(name)) return 'battery';
  if (/note|comment|remark|descr|what/.test(name)) return 'note';
  if (/session|^run$/.test(name)) return 'session';
  if (/device|phone|model/.test(name)) return 'device';
  if (/^(id|logid|entryid|rowid|uid|uuid)$/.test(name)) return 'entry_id';
  if (/^date$|^day$/.test(name)) return 'date';
  if (/time|when|logged|date/.test(name)) return 'time';
  return null;
};
const looksLikeNumber = (value) => /^[-+]?\d+([.,]\d+)?\s*(%|°?c)?$/i.test(value.trim());

const first = best.records[0].fields;
const guessed = first.map(fieldOf);
const header = guessed.some(Boolean) && !first.some(looksLikeNumber);
let columns;
let records;
if (header) {
  columns = guessed;
  records = best.records.slice(1);
} else {
  columns = settings.columns_without_header[String(first.length)];
  records = best.records;
  if (!columns) {
    return refuse(
      422,
      'no_header',
      `The file has no header row and ${first.length} columns. Without a header I can read ${Object.keys(settings.columns_without_header).join(', ')} columns (see Settings), or add a header row: time, device, battery, temperature, frame drops, note.`,
      { file_hash, delimiter: NAMES[best.separator], first_line: firstLine },
    );
  }
}
const at = (field) => columns.indexOf(field);
const missing = ['battery', 'temperature', 'frame_drops', 'note'].filter((field) => at(field) < 0);
if (missing.length > 0) {
  return refuse(422, 'missing_columns', `I cannot find a column for: ${missing.join(', ')}. The header I read is: ${first.join(' | ')}.`, {
    file_hash,
    delimiter: NAMES[best.separator],
    missing,
  });
}
if (at('device') < 0 && upload.device === '') {
  return refuse(
    422,
    'no_device',
    'I do not know which phone this log is from. Add ?device=NAME to the address the shortcut posts to, or a device column to the file.',
    { file_hash, delimiter: NAMES[best.separator] },
  );
}
if (records.length > settings.max_rows) {
  return refuse(413, 'too_many_rows', `The file has ${records.length} rows; the limit is ${settings.max_rows} (MAX_ROWS in Settings).`, { file_hash });
}

// --- read the values ---------------------------------------------------------
// "85%", "38,5", "38.5 °C" -> number. null when it is not a number.
const number = (value) => {
  const cleaned = value
    .trim()
    .replace(/\s*(%|°\s*c|°|c)$/i, '')
    .replace(',', '.');
  return /^[-+]?\d+(\.\d+)?$/.test(cleaned) ? Number(cleaned) : null;
};

// A time as written on the phone -> "2026-10-28T14:05:00", without a time zone:
// the comparison only needs the distance between two readings of one phone.
const two = (n) => String(n).padStart(2, '0');
function time(value) {
  const raw = value.trim();
  if (raw === '') return '';
  let parts = null;
  let m;
  if (/^\d{10}$|^\d{13}$/.test(raw)) {
    const date = new Date(Number(raw) * (raw.length === 10 ? 1000 : 1));
    parts = [date.getUTCFullYear(), date.getUTCMonth() + 1, date.getUTCDate(), date.getUTCHours(), date.getUTCMinutes(), date.getUTCSeconds()];
  } else if ((m = /^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})(?:[T ,]+(\d{1,2}):(\d{2})(?::(\d{2}))?(?:\.\d+)?\s*(am|pm)?)?\s*(?:z|[+-]\d{2}:?\d{2})?$/i.exec(raw))) {
    parts = [m[1], m[2], m[3], m[4] ?? 0, m[5] ?? 0, m[6] ?? 0, m[7]];
  } else if ((m = /^(\d{1,2})[-/.](\d{1,2})[-/.](\d{2}|\d{4})(?:[T ,]+(\d{1,2}):(\d{2})(?::(\d{2}))?\s*(am|pm)?)?$/i.exec(raw))) {
    const year = m[3].length === 2 ? `20${m[3]}` : m[3];
    parts = settings.day_first ? [year, m[2], m[1]] : [year, m[1], m[2]];
    parts.push(m[4] ?? 0, m[5] ?? 0, m[6] ?? 0, m[7]);
  }
  if (!parts) return null;
  let [year, month, day, hour, minute, second] = parts.slice(0, 6).map(Number);
  const half = String(parts[6] ?? '').toLowerCase();
  if (half === 'pm' && hour < 12) hour += 12;
  if (half === 'am' && hour === 12) hour = 0;
  const check = new Date(Date.UTC(year, month - 1, day, hour, minute, second));
  const real = check.getUTCFullYear() === year && check.getUTCMonth() === month - 1 && check.getUTCDate() === day && hour < 24 && minute < 60 && second < 60;
  return real ? `${year}-${two(month)}-${two(day)}T${two(hour)}:${two(minute)}:${two(second)}` : null;
}

const rows = [];
const rejected = [];
const seen = new Map();
let repeated = 0;
const cutOffHint = (record) => (record === records[records.length - 1] ? ' It is the last line: the file may be cut off, send it again when the export is complete.' : '');

for (const record of records) {
  const reject = (reason) => rejected.push({ line: record.line, reason });
  if (record.fields.length !== columns.length) {
    reject(`has ${record.fields.length} of ${columns.length} columns.${cutOffHint(record)}`);
    continue;
  }
  const cell = (field) => (at(field) < 0 ? '' : record.fields[at(field)].trim());

  const device = cell('device') || upload.device;
  if (device === '') {
    reject('no device');
    continue;
  }
  const battery = number(cell('battery'));
  if (battery === null || battery < 0 || battery > 100) {
    reject(`battery "${cell('battery')}" is not a number from 0 to 100`);
    continue;
  }
  const temperature = number(cell('temperature'));
  if (temperature === null || temperature < settings.temp_min || temperature > settings.temp_max) {
    reject(`temperature "${cell('temperature')}" is not a number from ${settings.temp_min} to ${settings.temp_max}`);
    continue;
  }
  const frame_drops = number(cell('frame_drops'));
  if (frame_drops === null || frame_drops < 0 || !Number.isInteger(frame_drops)) {
    reject(`frame drops "${cell('frame_drops')}" is not a whole number of 0 or more`);
    continue;
  }
  const written = at('date') >= 0 ? `${cell('date')} ${cell('time')}`.trim() : cell('time');
  const logged_at = time(written);
  if (logged_at === null) {
    reject(`time "${written}" is not a date and time I can read`);
    continue;
  }
  const note = cell('note').replace(/\r/g, '');
  const session = cell('session');
  const entry_id = cell('entry_id');

  // What makes two rows "the same reading": the app's own id when there is one,
  // else phone + time, else the whole row.
  const identity = entry_id !== '' ? ['id', device, entry_id] : logged_at !== '' ? ['time', device, logged_at] : ['row', device, battery, temperature, frame_drops, note];
  const row_key = sha256(identity.join('\u001f')).slice(0, 32);
  const content_hash = sha256([device, logged_at, battery, temperature, frame_drops, note, session].join('\u001f')).slice(0, 16);

  if (seen.has(row_key)) {
    if (seen.get(row_key) === content_hash) repeated++;
    else reject('same phone and time (or id) as an earlier line of this file, with different values. The earlier line was kept.');
    continue;
  }
  seen.set(row_key, content_hash);
  rows.push({ row_key, content_hash, line: record.line, device, logged_at, session, battery, temperature, frame_drops, note, entry_id });
}

if (rows.length === 0) {
  return refuse(422, 'no_rows', records.length === 0 ? 'The file has a header but no rows.' : `None of the ${records.length} rows could be used. See "rejected" for the reason per line.`, {
    file_hash,
    delimiter: NAMES[best.separator],
    rejected: rejected.slice(0, 20),
    rejected_count: rejected.length,
  });
}

return [
  {
    json: {
      ok: true,
      form: upload.form,
      filename: upload.filename,
      device: upload.device,
      file_hash,
      delimiter: NAMES[best.separator],
      header,
      rows_in_file: records.length,
      repeated_in_file: repeated,
      rows,
      rejected,
    },
  },
];

// Was exactly this file imported before? Only an import that finished counts:
// a run that failed half way must not block the next try. Two copies arriving
// at the same moment both get past this check; the row keys stop them later.
const token = $('Settings').first().json.token;
const earlier = $input
  .all()
  .map((item) => item.json)
  .filter((row) => row.token !== token && row.status === 'done')
  .sort((a, b) => a.id - b.id);
return [{ json: { duplicate_file: earlier.length > 0, first_imported_at: earlier[0]?.received_at ?? null } }];

// One item per row of the file, each marked with this run's token.
const { token } = $('Settings').first().json;
const file = $('Parse and check').first().json;
return file.rows.map((row) => ({ json: { ...row, token, file_hash: file.file_hash } }));

// Every row of the file is in the table now, next to any row with the same key
// that another run or an earlier import put there. The row with the lowest id
// for a key is the one that stays: ids only go up and every run looks after its
// own insert, so all runs agree on which one that is.
const { token } = $('Settings').first().json;
const first = new Map();
for (const { json: row } of $input.all()) {
  if (row.row_key === undefined) continue;
  const known = first.get(row.row_key);
  if (!known || row.id < known.id) first.set(row.row_key, row);
}
const added = [];
const remove = [];
const conflicts = [];
for (const { json: mine } of $('Claim rows').all()) {
  const winner = first.get(mine.row_key) ?? mine;
  if (winner.id === mine.id) {
    added.push(mine);
    continue;
  }
  remove.push(mine.id);
  // Same reading, other values: the stored row stays, and the phone is told.
  if (winner.content_hash !== mine.content_hash) {
    conflicts.push({
      device: mine.device,
      logged_at: mine.logged_at,
      entry_id: mine.entry_id,
      stored: { battery: winner.battery, temperature: winner.temperature, frame_drops: winner.frame_drops, note: winner.note },
      in_this_file: { battery: mine.battery, temperature: mine.temperature, frame_drops: mine.frame_drops, note: mine.note },
    });
  }
}
return [{ json: { token, added, remove, conflicts } }];

// One item per new row, with the column names of the Log tab.
return $('Keep the first')
  .first()
  .json.added.map((row) => ({
    json: {
      logged_at: row.logged_at,
      device: row.device,
      battery: row.battery,
      temperature: row.temperature,
      frame_drops: row.frame_drops,
      note: row.note,
      session: row.session,
      row_key: row.row_key,
    },
  }));

// The per-phone comparison, from every stored row. It is worked out again on
// each upload and on each GET, so it never drifts from the rows.
const { session_gap_minutes } = $('Settings').first().json;
const GAP_MS = session_gap_minutes * 60 * 1000;

// A row that lost the "first row per key" check may still be in the table for
// a moment while its run removes it. Count each key once.
const byKey = new Map();
for (const { json: row } of $input.all()) {
  if (row.row_key === undefined) continue;
  const known = byKey.get(row.row_key);
  if (!known || row.id < known.id) byKey.set(row.row_key, row);
}

const phones = new Map();
for (const row of byKey.values()) {
  if (!phones.has(row.device)) phones.set(row.device, []);
  phones.get(row.device).push({ ...row, at: row.logged_at ? Date.parse(`${row.logged_at}Z`) : null });
}

const round = (value, digits = 2) => (value === null ? null : Math.round(value * 10 ** digits) / 10 ** digits);
const mean = (values) => (values.length === 0 ? null : values.reduce((sum, value) => sum + value, 0) / values.length);

const devices = [];
for (const [device, rows] of phones) {
  // Oldest first; rows without a time keep the order they were stored in, at the end.
  rows.sort((a, b) => (a.at === null) - (b.at === null) || (a.at ?? 0) - (b.at ?? 0) || a.id - b.id);

  // Sessions: the "session" column when the file has one; else a pause longer
  // than SESSION_GAP_MINUTES starts a new one. A row with neither a session
  // name nor a time belongs to no session.
  const sessions = new Map();
  let counter = 0;
  let last = null;
  for (const row of rows) {
    let name = null;
    if (row.session) name = `named:${row.session}`;
    else if (row.at !== null) {
      if (last === null || row.at - last > GAP_MS) counter++;
      last = row.at;
      name = `gap:${counter}`;
    }
    if (name === null) continue;
    if (!sessions.has(name)) sessions.set(name, []);
    sessions.get(name).push(row);
  }

  const drains = [];
  let hours = 0;
  let dropsInTimedSessions = 0;
  for (const session of sessions.values()) {
    if (session.length < 2) continue;
    drains.push(session[0].battery - session[session.length - 1].battery);
    const timed = session.filter((row) => row.at !== null);
    const length = timed.length < 2 ? 0 : (timed[timed.length - 1].at - timed[0].at) / 3600000;
    if (length > 0) {
      hours += length;
      dropsInTimedSessions += timed.reduce((sum, row) => sum + row.frame_drops, 0);
    }
  }

  const temperatures = rows.map((row) => row.temperature);
  const times = rows.filter((row) => row.at !== null).map((row) => row.logged_at);
  devices.push({
    device,
    readings: rows.length,
    sessions: sessions.size,
    avg_temperature: round(mean(temperatures)),
    max_temperature: Math.max(...temperatures),
    avg_battery_drain_per_session: round(mean(drains)), // first reading minus last reading of a session, in battery percent
    frame_drops_total: rows.reduce((sum, row) => sum + row.frame_drops, 0),
    frame_drops_per_hour: hours > 0 ? round(dropsInTimedSessions / hours) : null,
    hours_logged: round(hours),
    first_reading: times[0] ?? null,
    last_reading: times[times.length - 1] ?? null,
  });
}
devices.sort((a, b) => a.device.localeCompare(b.device));

const show = (value, unit) => (value === null ? 'n/a' : `${value}${unit}`);
const summary = devices
  .map(
    (d) =>
      `${d.device}: ${d.readings} readings, avg ${show(d.avg_temperature, ' °C')}, max ${show(d.max_temperature, ' °C')}, drain ${show(d.avg_battery_drain_per_session, ' % per session')}, ${show(d.frame_drops_per_hour, ' frame drops per hour')}`,
  )
  .join('\n');

return [{ json: { rows_stored: byKey.size, devices, summary } }];

// One item per phone, with the column names of the Comparison tab.
return $('Compare devices')
  .first()
  .json.devices.map((device) => ({ json: device }));

// The one answer the caller gets: an HTTP code and a JSON body.
const ran = (name) => $(name).isExecuted;
const out = (code, body) => [{ json: { code, body } }];

// GET: only the comparison.
if (!ran('Phone posts CSV')) {
  const comparison = $('Compare devices').first().json;
  return out(200, { ok: true, rows_stored: comparison.rows_stored, comparison: comparison.devices, summary: comparison.summary });
}

const file = $('Parse and check').first().json;
if (!file.ok) {
  const { code, ok, ...rest } = file;
  return out(code, { ok: false, ...rest });
}

const about = { file_hash: file.file_hash, form: file.form, delimiter: file.delimiter, header: file.header, rows_in_file: file.rows_in_file };

if (ran('Take the rows back')) {
  return out(502, {
    ok: false,
    error: 'sheet_append_failed',
    message: 'The rows could not be added to the Google Sheet, so they were taken out of the data table again. Nothing is half stored. Send the file again.',
    ...about,
  });
}

const comparison = $('Compare devices').first().json;
const duplicate = $('Seen this file?').first().json.duplicate_file;
const kept = duplicate ? { added: [], conflicts: [] } : $('Keep the first').first().json;
const usable = file.rows.length;
return out(200, {
  ok: true,
  ...about,
  duplicate_file: duplicate, // true: exactly this file was imported before, nothing was looked at again
  added: kept.added.length,
  already_stored: usable - kept.added.length,
  conflicts: kept.conflicts.slice(0, 20), // same reading as a stored row but other values: the stored row was kept
  conflict_count: kept.conflicts.length,
  rejected: file.rejected.slice(0, 20), // lines that were not stored, with the reason
  rejected_count: file.rejected.length,
  rows_stored: comparison.rows_stored,
  comparison: comparison.devices,
  summary: comparison.summary,
});
